CREATE TABLE IF NOT EXISTS meta_table (id CHAR(26) PRIMARY KEY, table_code VARCHAR(80) NOT NULL UNIQUE, table_name VARCHAR(120) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS meta_field (id CHAR(26) PRIMARY KEY, table_id CHAR(26) NOT NULL, field_code VARCHAR(80) NOT NULL, field_type VARCHAR(30) NOT NULL, required BOOLEAN NOT NULL DEFAULT FALSE, sort_order INT NOT NULL DEFAULT 0, CONSTRAINT fk_meta_field_table FOREIGN KEY(table_id) REFERENCES meta_table(id));
